# region: emit
def emit(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: gather
def gather(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: digest
def digest(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: sift
def sift(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return sift(intake(digest(fold(gather(emit(raw))))))

